import{_ as t,c as e,o as p,ah as s,ao as a,ap as n}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"連一隻麻雀，祂都記得——牠從未被遺忘","description":"耶穌說，一隻麻雀掉在地上，天父都知道。從馬太福音與詩篇看神對動物的看顧，以及牠的一生如何被珍視。","frontmatter":{"title":"連一隻麻雀，祂都記得——牠從未被遺忘","description":"耶穌說，一隻麻雀掉在地上，天父都知道。從馬太福音與詩篇看神對動物的看顧，以及牠的一生如何被珍視。"},"headers":[],"relativePath":"pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"pets-in-heaven/not-one-sparrow-forgotten.md"}'),r={name:"pets-in-heaven/not-one-sparrow-forgotten.md"};function i(l,o,c,h,d,u){return p(),e("div",null,[...o[0]||(o[0]=[s('<div class="pl-quote"><p>「牠只是一隻小動物。世界會記得牠嗎？還是我一個人在懷念牠？」</p><p class="pl-quote-soft">耶穌回答過這個問題，而祂的答案比我們想像的更溫柔。</p></div><section class="pl-section"><h2>一、耶穌說：一隻麻雀掉在地上，天父都知道</h2><blockquote><p><strong>馬太福音 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>在耶穌的時代，麻雀是最便宜的東西之一——兩隻賣一分銀子。那是一種「沒人會特別在意」的生命。</p><p>耶穌卻說：<strong>如果沒有你們的天父，一隻也不會掉在地上。</strong></p><p>這句話裡的「掉落」（fall），指的正是死亡。耶穌在說的就是：一隻最便宜的小鳥死掉，都不是神不知道、不在意的意外。牠的離世，在神那裡是有記錄、被看見的。</p><p>如果你的牠是一隻小小的、別人眼中「不過是動物」的同伴——這節經文就是為你寫的。神連麻雀都記得，祂怎麼會忘記你的牠。</p></section><section class="pl-section"><h2>二、祂餵養牠，一天都沒有漏掉</h2><blockquote><p><strong>詩篇 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>大衛在另一處也說：</p><blockquote><p><strong>詩篇 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>「救護人和牲畜」——原文裡「牲畜」就是野地與家中的動物。這句話把動物放在神看顧的名單裡，不是順便一提，而是並列。</p><p>這意味著什麼？意味著你的牠從出生到離開，每一餐、每一個冬天、每一次你不在家的時候，都有那位神在看顧。你以為你一個人在照顧牠，其實你是在和神一起照顧牠。</p></section><section class="pl-section"><h2>三、牠屬於神——這是最安心的部分</h2><blockquote><p><strong>詩篇 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>神說：「森林中的百獸是我的，千山上的牲畜也是我的。山中的飛鳥我都知道。」</p><p>你的牠，從來不是你「擁有」的財產，而是神交給你照顧的禮物。而當禮物的主人收回去的時候，祂不是把它丟掉——祂是把它<strong>帶回自己那裡</strong>。</p><p>你不知道祂會怎麼照顧牠、牠現在在哪裡、牠是否記得你的聲音。但你知道那是誰的手：是那雙連麻雀都數過的手。</p><p class="pl-quote-soft">如果你今天只能記住一句話，請記住這一句：</p></section><div class="pl-quote"><p>「牠從來沒有離開神的目光。現在也沒有。」</p></div><section class="pl-section"><h2>可以試著這樣禱告</h2><p>「主啊，謝謝祢把牠交給我照顧了這些年。<br>謝謝祢在我看不見的地方也看顧牠。<br>現在我不再把牠抱在懷裡了，但我知道祢的手比我更大。<br>求祢照顧牠，就像祢照顧每一隻麻雀一樣。<br>也求祢照顧我，因為我很想牠。阿們。」</p><p><a href="/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 下一篇：<a href="/pets-in-heaven/rainbow-bridge-covenant">彩虹橋的彼端</a></p></section><div class="pl-cta"><h2>牠有一個名字。</h2><p>在 PetLoss 裡寫下牠的名字和一個牠的小習慣——那些別人不知道、只有你知道的細節。它們值得被保存。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下載</a></div><div class="pl-bible"><h3>讓聖經的話繼續陪你</h3><p>本文引用的經文都出自聖經。用《彩虹聖經》隨時閱讀神的話、設定每日經文小工具，在想念牠的日子裡仍有一盞燈。</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="Rainbow Bible 聖經小工具顯示 2 Timothy 2:13" loading="lazy"><figcaption>每日經文放在主畫面</figcaption></figure><figure><img src="'+n+'" alt="Rainbow Bible App 的「天堂裡的毛孩」主題，顯示 Matthew 10:29-31" loading="lazy"><figcaption>切換到「天堂裡的毛孩」主題讀經</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 取得《彩虹聖經》</a></div>',8)])])}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
